binary=sys.argv[1]
with tempfile.TemporaryDirectory() as temporary:
    path=Path(temporary)/"study.csv"
    for case in cases:
        with path.open("w",newline="",encoding="utf-8") as f:
            writer=csv.writer(f)
            writer.writerow(case["cols"])
            writer.writerows(case["x"])
        args=[binary,case["cmd"],str(path),*map(str,case["p"])]
        run=subprocess.run(args,text=True,capture_output=True,timeout=20)
        assert run.returncode==0,(case["cmd"],run.stderr)
        rows=[line.split(",") for line in run.stdout.strip().splitlines()]
        actual=[float(r[1]) for r in rows]
        assert len(actual)==len(case["expected"]),(case["cmd"],actual,case["expected"])
        assert [int(r[0]) for r in rows]==list(range(len(rows))),case["cmd"]
        for a,b in zip(actual,case["expected"]):
            assert math.isfinite(a) and math.isclose(a,b,rel_tol=1e-7,abs_tol=1e-7),(case["cmd"],actual,case["expected"])
        for invalid in ([binary,case["cmd"],str(path)+".missing",*map(str,case["p"])],
                        [binary,case["cmd"],str(path),*map(str,case["p"]),"not-a-number"]):
            run=subprocess.run(invalid,text=True,capture_output=True,timeout=20)
            assert run.returncode==1,(invalid,run.stdout,run.stderr)
            assert "Quant research input error:" in run.stderr,invalid
print(f"PASS: {len(cases)} CSV research commands with exact vector outputs and {2*len(cases)} invalid-input checks")
